    static void Near(double[] actual,double[] expected,double tolerance,string label)
    {
        double dot=0;for(int i=0;i<4;i++)dot+=actual[i]*expected[i];
        for(int i=0;i<4;i++)if(double.IsNaN(actual[i]) || Math.Abs(actual[i]-(dot<0?-expected[i]:expected[i]))>tolerance)
            throw new Exception(label+" quaternion mismatch");
    }
    static void Check(string label,double[] a,double[] b,double t,double[] expected)
    {
        double[] actual=KrakenEndpointRotation.Interpolate(a,b,t);Near(actual,expected,2e-12,label);
        for(int i=0;i<4;i++)actual[i]=(float)actual[i];Near(actual,expected,5e-8,label+" float boundary");
        double[] reversed=new double[4];for(int i=0;i<4;i++)reversed[i]=-b[i];
        Near(KrakenEndpointRotation.Interpolate(a,reversed,t),expected,2e-12,label+" shortest arc");count++;
    }
